import React, { useState, useEffect } from 'react';
import axios from 'axios';

const EmployeeAssetsPage = () => {
  const [allAssets, setAllAssets] = useState([]); // Will hold the original, full list of assets
  const [isLoading, setIsLoading] = useState(true);
  // --- NEW: State to hold the user's search query ---
  const [searchQuery, setSearchQuery] = useState('');

  useEffect(() => {
    const fetchAndPrepareAssets = async () => {
      setIsLoading(true);
      try {
        const response = await axios.get('http://127.0.0.1:8000/api/employees/');
        let employeesData = response.data.results || response.data || [];

        const simulatedAssets = employeesData.map((employee, index) => ({
          id: `ASSET-${employee.id}`,
          assetId: `LP-00${123 + employee.id}`,
          type: ['Laptop', 'Monitor', 'Phone', 'ID Card'][index % 4],
          model: ['MacBook Pro 16"', 'Dell UltraSharp U27', 'iPhone 14 Pro', 'Faculty Access Card'][index % 4],
          status: ['Assigned', 'In Repair', 'Assigned', 'Assigned'][index % 4],
          custodian: `${employee.firstName} ${employee.lastName}`,
          department: employee.department,
          date: employee.joiningDate,
        }));

        setAllAssets(simulatedAssets); // Store the full list
      } catch (error) {
        console.error("Error fetching data for assets:", error);
      } finally {
        setIsLoading(false);
      }
    };

    fetchAndPrepareAssets();
  }, []);

  // --- NEW: Filtered assets derived from the search query ---
  const filteredAssets = allAssets.filter(asset =>
    // Check if the custodian's name (lowercase) includes the search query (lowercase)
    asset.custodian.toLowerCase().includes(searchQuery.toLowerCase()) ||
    // Also check if the asset ID (lowercase) includes the search query
    asset.assetId.toLowerCase().includes(searchQuery.toLowerCase())
  );

  const getStatusBadge = (status) => { /* ... (same as before) ... */ };

  return (
    <div className="p-8">
      {/* === UPDATED HEADER SECTION === */}
      <div className="flex justify-between items-center mb-6">
          <div>
              <h1 className="text-3xl font-bold text-text-light dark:text-text-dark">Asset Management</h1>
              <p className="text-sm text-subtext-light">Search and view all university assets assigned to staff.</p>
          </div>
          {/* Replaced button with a search bar */}
          <div className="relative w-full max-w-xs">
              <span className="material-icons absolute left-3 top-1/2 -translate-y-1/2 text-subtext-light">search</span>
              <input 
                type="text" 
                placeholder="Search by Employee or Asset ID..." 
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="w-full pl-10 pr-4 py-2 rounded-lg bg-card-light dark:bg-gray-800 border border-border-light dark:border-border-dark"
              />
          </div>
      </div>

      <div className="overflow-x-auto rounded-lg border border-border-light dark:border-border-dark bg-card-light dark:bg-card-dark">
        {isLoading ? (
            <div className="text-center py-10 text-subtext-light">Loading asset data...</div>
        ) : (
            <table className="w-full text-left text-sm">
                <thead className="bg-gray-50 text-xs uppercase">
                    {/* ... (table header is the same) ... */}
                </thead>
                <tbody>
                    {/* --- We now map over the NEW filteredAssets array --- */}
                    {filteredAssets.map(asset => (
                        <tr key={asset.id} className="border-b hover:bg-gray-50">
                            <td className="px-6 py-4 font-medium">{asset.assetId}</td>
                            <td className="px-6 py-4">{asset.type}</td>
                            <td className="px-6 py-4">{asset.model}</td>
                            <td className="px-6 py-4">{getStatusBadge(asset.status)}</td>
                            <td className="px-6 py-4 font-semibold text-text-light dark:text-white">{asset.custodian}</td>
                            <td className="px-6 py-4">{asset.department}</td>
                            <td className="px-6 py-4">{asset.date}</td>
                        </tr>
                    ))}
                </tbody>
            </table>
        )}
      </div>
    </div>
  );
};

// ... (getStatusBadge function remains the same)

export default EmployeeAssetsPage;
